import unittest
from collections import UserDict

from solution import ConfigError, read_required


class ReadRequiredTests(unittest.TestCase):
    def test_nested_lookup_and_deep_copy(self):
        leaf = {"items": [1, {"x": 2}]}
        config = {"service": {"settings": leaf}}
        result = read_required(config, ["service", "settings"])
        self.assertEqual(result, leaf)
        self.assertIsNot(result, leaf)
        self.assertIsNot(result["items"], leaf["items"])
        result["items"][1]["x"] = 99
        result["items"].append(3)
        self.assertEqual(config, {"service": {"settings": {"items": [1, {"x": 2}]}}})

    def test_mapping_subclasses_and_tuple_path(self):
        config = UserDict({"a": UserDict({"b": 4})})
        self.assertEqual(read_required(config, ("a", "b")), 4)

    def test_missing_key_raises_config_error_naming_component(self):
        with self.assertRaises(ConfigError) as caught:
            read_required({"a": {}}, ["a", "missing"])
        self.assertIn("missing", str(caught.exception))

    def test_non_mapping_encountered_names_component(self):
        with self.assertRaises(ConfigError) as caught:
            read_required({"a": 3}, ["a", "next"])
        self.assertIn("next", str(caught.exception))

    def test_invalid_config_type(self):
        for config in (None, [], [("a", 1)], "text"):
            with self.subTest(config=config), self.assertRaises(TypeError):
                read_required(config, ["a"])

    def test_path_container_type(self):
        for path in ("a", {"a"}, None):
            with self.subTest(path=path), self.assertRaises(TypeError):
                read_required({}, path)

    def test_invalid_path_contents(self):
        for path in ([], (), [""], ["a", ""], ["a", 1]):
            with self.subTest(path=path), self.assertRaises(ValueError):
                read_required({}, path)


if __name__ == "__main__":
    unittest.main()

